#!/usr/bin/env node
/**
 * QSkyway — build a city digital-twin (20 m height field) from OpenStreetMap.
 *
 * WHY THIS EXISTS: the three committed twins (Astana, NYC, Tokyo — 524 KB, the
 * foundation every route, ceiling check and justification document is computed
 * over) were generated on 2026-07-13 by throwaway scripts that were never
 * committed. Their own headers say "Generated by rebuild_tokyo.mjs" — a file
 * that does not exist in this repository. That means the module's most load-
 * bearing data could not be refreshed, audited against OSM, or extended to a
 * fourth city. Committed data whose provenance cannot be re-run is a claim we
 * cannot check; this script turns it back into one we can.
 *
 * Usage:
 *   node scripts/fetch-city-twin.mjs astana --compare   (diff vs committed, writes nothing)
 *   node scripts/fetch-city-twin.mjs astana --write     (replace the committed twin)
 *
 * NOTE: `> src/routes/qskyway.city.ts` looks equivalent to --write and is NOT.
 * The shell truncates the target before node starts, and this script READS the
 * committed twin (vertiports, and the comparison itself), so redirection would
 * hand it an empty file. --write reads first, then replaces.
 *
 * HONEST SCOPE — read before regenerating anything:
 *  - OSM is a live database. Re-running this will NOT reproduce the 2026-07-13
 *    files byte-for-byte: buildings get added, heights get tagged. Use
 *    --compare to see the drift as a number before overwriting a twin.
 *  - Tokyo is built from TWO sources: OSM footprints reconciled with MLIT
 *    Project PLATEAU LOD2 roof outlines (~420 MB of CityGML per run; use
 *    --plateau-cache to keep it off the wire while iterating). Until 2026-07-27
 *    this script refused to emit tokyo at all, because rebuilding it from OSM
 *    alone would have downgraded measured heights to guesses while every number
 *    in the UI kept looking the same. The cost of that refusal was that Tokyo's
 *    FOOTPRINTS could never be refreshed either, and they had drifted 565 grid
 *    cells behind reality. A city whose heights come from elsewhere needs that
 *    source wired in, not an exemption.
 */

import fs from "node:fs";

// Сколько известных высот того же типа нужно, чтобы квантиль считался ответом
// города, а не совпадением двух домов.
const TYPE_MEDIAN_MIN_SAMPLES = 3;
// Берём 75-й процентиль распределения этого типа, не медиану: см. замер в блоке
// подстановки перед rasterize.
const TYPE_QUANTILE = 0.75;
// Типы, которые о высоте не сообщают ничего.
const UNINFORMATIVE_TYPES = new Set(["yes", "building", "construction", "roof"]);

const OVERPASS = [
  "https://overpass-api.de/api/interpreter",
  "https://overpass.kumi.systems/api/interpreter",
];

import {
  METRES_PER_LEVEL, PARAPET_M, DEFAULT_HEIGHT_M, CELL, M_PER_LAT, M_PER_LON_EQ,
  projection, parseMetres, heightOf, ringsOf, inRing, rasterize, overpassProblem, overpassBodyProblem, heightOutliers,
} from "./lib/city-twin-geometry.mjs";
import { parsePlateauGml } from "./lib/plateau-heights.mjs";
import { parseNycBuildings, nycBuildingsQuery } from "./lib/nyc-open-data.mjs";
import { reconcileMeasuredOutlines } from "./lib/measured-outlines.mjs";

// The height model, the projection and the rasterizer live in
// scripts/lib/city-twin-geometry.mjs so they can be unit-tested; this file is
// the part that talks to the network and to disk. Constants are re-exported
// there and mirrored by SRC_CLEARANCE in src/routes/qskyway.ts.

const CITIES = {
  astana: {
    name: "Астана — центр (бульвар Нуржол)",
    bbox: { minLat: 51.1183717, maxLat: 51.1356973, minLon: 71.4104119, maxLon: 71.4432041 },
    exportName: "CITY",
    committed: "qskyway.city.ts",
    // Vertiports are a PRODUCT placement decision (where an operator would put
    // pads), not an OSM fact — so they are config here, never re-derived.
    vertiports: [
      { c: 64, r: 44, x: 1290, y: 890 }, { c: 2, r: 93, x: 50, y: 1870 },
      { c: 2, r: 2, x: 50, y: 50 }, { c: 112, r: 93, x: 2250, y: 1870 },
      { c: 112, r: 2, x: 2250, y: 50 }, { c: 53, r: 93, x: 1070, y: 1870 },
      { c: 17, r: 48, x: 350, y: 970 },
    ],
    header: [
      "// QSkyway city digital-twin — real Astana buildings from OpenStreetMap (Overpass),",
      "// rasterized to a 20m height field. v2: per-building height provenance (hs) +",
      "// per-cell source grid + dataQuality summary. Regenerate with:",
      "//   node scripts/fetch-city-twin.mjs astana --write",
      "/* eslint-disable */",
      "export interface CityData {",
      "  city: string;",
      "  bbox: { minLat: number; maxLat: number; minLon: number; maxLon: number };",
      "  meters: { w: number; h: number };",
      "  grid: { cols: number; rows: number; cell: number; heights: number[]; src: number[] };",
      "  buildings: { h: number; hs: number; r: number[][] }[];",
      "  vertiports: { c: number; r: number; x: number; y: number }[];",
      "  dataQuality: {",
      "    total: number; measured: number; derived: number; guessed: number;",
      "    measuredPct: number; realPct: number; source: string; note: string;",
      "    /** Heights that tower over the rest of the city — a wrong tag is trusted",
      "     *  as completely as a right one, so it is published, not hidden.",
      "     *  Absent when there is nothing to report. */",
      "    suspect?: { i: number; h: number; why: string;",
      "                 /** set when the height stands out from the city */ times?: number;",
      "                 /** set when the source's own floor count contradicted its height tag */",
      "                 was?: number; levels?: number }[];",
      "  };",
      "}",
    ].join("\n"),
  },
  nyc: {
    name: "Нью-Йорк — Мидтаун (Манхэттен)",
    bbox: { minLat: 40.7474728, maxLat: 40.7629936, minLon: -74.0002478, maxLon: -73.9758674 },
    exportName: "CITY_NYC",
    committed: "qskyway.city.nyc.ts",
    vertiports: null, // read from the committed twin (see loadCommitted)
    // New York surveys its own buildings and publishes the result as an API.
    // Before this was wired in, 205 Midtown buildings sat in the obstacle grid
    // at the blind 12 m default while the city had a measured height for them.
    measured: {
      kind: "socrata",
      label: "NYC Open Data height_roof (photogrammetric survey, dataset 5zhs-2jue)",
      // height_roof is in FEET and stops at the roof — see nyc-open-data.mjs.
      marginM: 300,
      nearRadiusM: 20,
    },
    header: [
      "// QSkyway city digital-twin — NYC Midtown (Manhattan), real OpenStreetMap buildings",
      "// (Overpass, ODbL), 20m height field. v2: height provenance + dataQuality.",
      "// Regenerate with:",
      "//   node scripts/fetch-city-twin.mjs nyc --write",
      "/* eslint-disable */",
      'import type { CityData } from "./qskyway.city";',
    ].join("\n"),
  },
  tokyo: {
    name: "Токио — Ниси-Синдзюку",
    bbox: { minLat: 35.683592, maxLat: 35.6978747, minLon: 139.6879457, maxLon: 139.7037075 },
    exportName: "CITY_TOKYO",
    committed: "qskyway.city.tokyo.ts",
    vertiports: null,
    // Tokyo's heights come from a second regulator-published source, so the twin
    // is OSM footprints reconciled with PLATEAU roof outlines. Until 2026-07-27
    // this city could not be regenerated at all and its footprints were frozen
    // at 2026-07-13 — see plateau-heights.mjs for what that cost.
    measured: {
      kind: "citygml",
      label: "PLATEAU LOD2 measuredHeight (MLIT Project PLATEAU, Shinjuku-ku 2025, CityGML spec 5.0)",
      // Per-3rd-mesh CityGML for Shinjuku-ku. These are the four meshes covering
      // the Nishi-Shinjuku bbox. The asset id in the path is issued by the
      // PLATEAU CMS per release: when a new year ships, the old URLs keep
      // working but stop being current — refresh them from the CMS manifest
      // rather than editing the year in place, and re-run --compare first.
      assets: [
        "https://assets.cms.plateau.reearth.io/assets/84/48ebed-93d8-4196-bdda-e1db9590d3d1/13104_shinjuku-ku_pref_2025_citygml_1_op/udx/bldg/53394525_bldg_6697_op.gml",
        "https://assets.cms.plateau.reearth.io/assets/84/48ebed-93d8-4196-bdda-e1db9590d3d1/13104_shinjuku-ku_pref_2025_citygml_1_op/udx/bldg/53394526_bldg_6697_op.gml",
        "https://assets.cms.plateau.reearth.io/assets/84/48ebed-93d8-4196-bdda-e1db9590d3d1/13104_shinjuku-ku_pref_2025_citygml_1_op/udx/bldg/53394535_bldg_6697_op.gml",
        "https://assets.cms.plateau.reearth.io/assets/84/48ebed-93d8-4196-bdda-e1db9590d3d1/13104_shinjuku-ku_pref_2025_citygml_1_op/udx/bldg/53394536_bldg_6697_op.gml",
      ],
      // A building just outside the city still stands over footprints inside it.
      // Cropping PLATEAU to the exact bbox lost the measured height of 112
      // buildings, a 199 m tower among them.
      marginM: 300,
      nearRadiusM: 20,
    },
    header: [
      "// QSkyway city digital-twin — Токио, Ниси-Синдзюку. OpenStreetMap footprints",
      "// (Overpass, ODbL) reconciled with MLIT Project PLATEAU LOD2 roof outlines and",
      "// measuredHeight (CityGML, Shinjuku-ku 2025). Neither source is a subset of the",
      "// other, so the twin carries both. Regenerate with:",
      "//   node scripts/fetch-city-twin.mjs tokyo --write",
      "/* eslint-disable */",
      'import type { CityData } from "./qskyway.city";',
    ].join("\n"),
  },
};

const cityId = process.argv[2];
const compareOnly = process.argv.includes("--compare");
const city = CITIES[cityId];
if (!city) {
  console.error(`unknown city "${cityId}" — known: ${Object.keys(CITIES).join(", ")}`);
  process.exit(1);
}
// Optional on-disk cache for the CityGML archives. Only ever a speed-up for
// repeated local runs: the files are content-addressed by their URL basename and
// the script re-downloads whatever is missing.
const cacheFlag = process.argv.indexOf("--plateau-cache");
const plateauCache = cacheFlag > 0 ? process.argv[cacheFlag + 1] : null;

// ── projection ────────────────────────────────────────────────────────────────
const { minLat, maxLat, minLon, maxLon } = city.bbox;
const { proj, w: W, h: H, cols: COLS, rows: ROWS } = projection(city.bbox);

// ── fetch ─────────────────────────────────────────────────────────────────────
const query = `[out:json][timeout:180];
(way["building"](${minLat},${minLon},${maxLat},${maxLon});
 relation["building"](${minLat},${minLon},${maxLat},${maxLon}););
out geom;`;

async function overpass() {
  let lastErr;
  for (const host of OVERPASS) {
    for (let attempt = 1; attempt <= 3; attempt++) {
      try {
        // Raw query body, not form-encoded: overpass-api.de answers 406 to the
        // form-encoded shape. A descriptive User-Agent is also expected — the
        // instance is a donated public service and identifying the client is
        // the price of using it politely.
        const res = await fetch(host, {
          method: "POST",
          body: query,
          headers: {
            "Content-Type": "text/plain",
            "User-Agent": "AEVION-QSkyway/1.0 (city twin builder; contact via github.com/Dossymbek281078/AEVION)",
          },
          signal: AbortSignal.timeout(240_000),
        });
        // 429/504 are Overpass telling us to wait, not that the data is absent.
        if (res.status === 429 || res.status === 504) throw new Error(`Overpass HTTP ${res.status} (busy)`);
        if (!res.ok) throw new Error(`Overpass HTTP ${res.status}`);
        // A busy instance says so with HTTP 200 and an HTML page; parsing that
        // as JSON throws something about token '<' and loses the server's own
        // explanation.
        const body = await res.text();
        const bodyProblem = overpassBodyProblem(body);
        if (bodyProblem) throw new Error(bodyProblem);
        const json = JSON.parse(body);
        // A truncated answer arrives as HTTP 200 with fewer buildings and a
        // remark — never as an error. Treat it as a failure, not as data.
        const problem = overpassProblem(json);
        if (problem) throw new Error(problem);
        return json.elements;
      } catch (e) {
        lastErr = e;
        process.stderr.write(`  ${host} attempt ${attempt}: ${e.message}\n`);
        if (attempt < 3) await new Promise((r) => setTimeout(r, 15_000 * attempt));
      }
    }
  }
  throw lastErr;
}

// ── build ─────────────────────────────────────────────────────────────────────
function loadCommitted(file) {
  const path = new URL(`../src/routes/${file}`, import.meta.url);
  const text = fs.readFileSync(path, "utf8");
  const start = text.indexOf('{"city"');
  if (start < 0) throw new Error(`cannot locate data literal in ${file}`);
  return JSON.parse(text.slice(start, text.lastIndexOf("};") + 1));
}


process.stderr.write(`QSkyway twin: ${cityId} — querying Overpass…\n`);
const elements = await overpass();

const buildings = [];
// Parallel array, diagnostics only — never emitted, so the twin keeps exactly
// the shape src/routes/qskyway.ts already consumes.
const meta = [];
// Тип здания из OSM. Тоже параллельным массивом и тоже не отгружается: он нужен
// ровно для одного — подставить слепой высоте медиану её собственного типа
// (см. блок перед rasterize). В самом твине типу делать нечего, там его никто
// не читает, а лишнее поле в 500-килобайтном файле надо было бы поддерживать.
const buildingTypes = [];
const contradicted = [];
for (const el of elements) {
  const { h, hs, stated, contradicted: was } = heightOf(el.tags);
  for (const r of ringsOf(el, proj)) {
    if (was !== undefined) {
      contradicted.push({ i: buildings.length, h, was, levels: Number(el.tags["building:levels"]) });
    }
    buildings.push({ h, hs, r, stated });
    buildingTypes.push(String(el.tags?.building || "yes"));
    meta.push({ id: `${el.type}/${el.id}`, name: el.tags?.name ?? el.tags?.["name:en"] ?? null });
  }
}
if (!buildings.length) throw new Error("Overpass returned no usable building footprints for this bbox");

// ── measured heights from a second source (PLATEAU) ───────────────────────────
let sourceLabel = "OpenStreetMap (Overpass, ODbL)";
// Легенда едет в отгружаемом твине и показывается человеку — до 28.07.2026 она
// гласила «hs 0=измерено(height tag)», то есть описывала правило, которое к тому
// моменту уже отменили. Легенда, описывающая не тот код, хуже её отсутствия:
// она выглядит как проверенное утверждение о происхождении данных.
let provenanceNote =
  "hs 0=обмерено властями (в этом городе такого источника нет) " +
  "1=выведено(тег height из OSM либо levels×3.2+1.6м парапет) 2=угадано(дефолт 12м). " +
  "Тег OSM ставит участник проекта, а не служба обмера, поэтому он выведенный: " +
  "ему добавляется страховочный просвет. Появление LiDAR/LOD2/3D Tiles поднимет " +
  "measuredPct и просвет снизит.";

if (city.measured) {
  const { kind, assets, marginM, nearRadiusM, label } = city.measured;
  const mPerLon = M_PER_LON_EQ * Math.cos((((minLat + maxLat) / 2) * Math.PI) / 180);
  const wide = {
    minLat: minLat - marginM / M_PER_LAT, maxLat: maxLat + marginM / M_PER_LAT,
    minLon: minLon - marginM / mPerLon, maxLon: maxLon + marginM / mPerLon,
  };

  // Every source hands back the same shape: { h in METRES, ring as [lon, lat] }.
  // Normalising here and not at the reconciler is deliberate — a source's axis
  // order and unit are facts about that source, and the further they travel
  // un-normalised the more places can read them the wrong way round.
  const outlines = [];
  if (kind === "citygml") {
    for (const url of assets) {
      const name = url.slice(url.lastIndexOf("/") + 1);
      const cached = plateauCache ? `${plateauCache}/${name}` : null;
      let gml;
      if (cached && fs.existsSync(cached)) {
        gml = fs.readFileSync(cached, "utf8");
        process.stderr.write(`  PLATEAU ${name}: cached\n`);
      } else {
        process.stderr.write(`  PLATEAU ${name}: downloading…\n`);
        const res = await fetch(url, {
          headers: { "User-Agent": "AEVION-QSkyway/1.0 (city twin builder)" },
          signal: AbortSignal.timeout(600_000),
        });
        if (!res.ok) throw new Error(`PLATEAU ${name}: HTTP ${res.status}`);
        gml = await res.text();
        if (cached) fs.writeFileSync(cached, gml);
      }
      const got = parsePlateauGml(gml, wide);
      process.stderr.write(`  PLATEAU ${name}: ${got.length} roof outlines\n`);
      // CityGML is EPSG:6697, latitude first.
      for (const g of got) outlines.push({ h: g.h, ring: g.ring.map(([lat, lon]) => [lon, lat]) });
    }
  } else if (kind === "socrata") {
    const url = nycBuildingsQuery(wide);
    process.stderr.write(`  NYC Open Data: querying…\n`);
    const res = await fetch(url, {
      headers: { "User-Agent": "AEVION-QSkyway/1.0 (city twin builder)" },
      signal: AbortSignal.timeout(600_000),
    });
    if (!res.ok) throw new Error(`NYC Open Data: HTTP ${res.status}`);
    const rows = await res.json();
    const got = parseNycBuildings(rows);
    process.stderr.write(`  NYC Open Data: ${rows.length} rows, ${got.length} outlines with a height\n`);
    // Socrata geometry is GeoJSON, longitude first — already the shape we want.
    outlines.push(...got);
  } else {
    throw new Error(`${cityId}: unknown measured-height source kind "${kind}"`);
  }

  // An empty answer is the failure mode that must never reach --write: the twin
  // would keep its shape, lose every measured height, and read as a successful
  // regeneration. Louder than a downgraded file.
  if (!outlines.length) {
    throw new Error(
      `${cityId}: the measured-height source returned no outlines inside the bbox. Refusing to ` +
      `emit a twin that would silently downgrade measured heights to OSM guesses.`,
    );
  }

  const projected = outlines.map((p) => ({ h: p.h, ring: p.ring.map(([lon, lat]) => proj(lon, lat)) }));
  const { heights: measuredAt, unmatched } = reconcileMeasuredOutlines(
    buildings.map((b) => b.r), projected, { nearRadiusM },
  );

  // THE RULE, and each branch is a different claim about what we know:
  //  contained + OSM also measured → the TALLER of two measurements. PLATEAU
  //    measures to the roof deck, OSM tags often include the mast; neither is
  //    uniformly higher (measured in Nishi-Shinjuku: PLATEAU wins 170 times,
  //    OSM 365). For an obstacle grid the taller measurement is the one to fly
  //    over, and both being measurements keeps hs=0 honest.
  //  contained only → PLATEAU, measured.
  //  near → weak identity. Never overrules a height OSM states, and is marked
  //    DERIVED (hs=1), not measured: the value is surveyed, the identification
  //    is ours, and hs=1 is exactly the class SRC_CLEARANCE gives extra room.
  let contained = 0, near = 0, plateauTaller = 0, osmTaller = 0;
  buildings.forEach((b, i) => {
    const p = measuredAt[i];
    if (p.how === "contained") {
      contained++;
      // Условие — «у OSM есть СВОЁ число», а не «оно считается обмером».
      //
      // Причина брать большее физическая: съёмка меряет крышу, тег часто
      // включает мачту. К классу доверия это отношения не имеет, и когда правило
      // было привязано к hs===0, оно молча выключилось, стоило понизить класс
      // тега OSM (28.07.2026). Цена выключения проверяется тестом: максимум
      // твина Нью-Йорка падал с 443 до 427 — то есть коридор шёл сквозь антенну
      // Эмпайр-Стейт, потому что съёмка города меряет крыши без мачт.
      //
      // Прикидке по этажам и подставленному значению по умолчанию спорить с
      // обмером нечем — там побеждает съёмка.
      if (b.stated) {
        if (p.h > b.h) plateauTaller++; else if (b.h > p.h) osmTaller++;
        b.h = Math.round(Math.max(p.h, b.h));
      } else {
        b.h = Math.round(p.h);
      }
      b.hs = 0;
    } else if (p.how === "near" && b.hs !== 0 && p.h > b.h) {
      near++;
      b.h = Math.round(p.h);
      b.hs = 1;
    }
  });

  // Outlines PLATEAU surveyed that OSM has no footprint for at all. Only those
  // standing inside the city are added — the rest sit in the margin ring, which
  // exists to match edge buildings and was never queried from OSM, so "no OSM
  // counterpart" there means nothing.
  let added = 0;
  for (const i of unmatched) {
    const ring = projected[i].ring;
    let sx = 0, sy = 0;
    for (const [x, y] of ring) { sx += x; sy += y; }
    const cx = sx / ring.length, cy = sy / ring.length;
    if (cx < 0 || cy < 0 || cx > COLS * CELL || cy > ROWS * CELL) continue;
    buildings.push({
      h: Math.round(projected[i].h), hs: 0,
      r: ring.map(([x, y]) => [Math.round(x * 10) / 10, Math.round(y * 10) / 10]),
    });
    meta.push({ id: `${kind}/${i}`, name: null });
    added++;
  }

  process.stderr.write(
    `  ${kind}: ${contained} footprints identified by containment (${plateauTaller} raised, ` +
    `${osmTaller} kept OSM's taller measurement), ${near} by proximity, ${added} outlines added ` +
    `that OSM has no footprint for\n`,
  );

  sourceLabel = `OSM footprints (ODbL) + ${label}`;
  provenanceNote =
    `hs 0=обмерено(${label}; где источник обмера опознал контур уверенно и OSM НАЗВАЛ ` +
    "свою высоту — берётся большая: обмер меряет крышу, а тег часто включает мачту, " +
    "и облетать надо мачту) 1=выведено(контур обмера опознан по близости, а не по " +
    "вложенности; либо тег height из OSM без подтверждения обмером; либо " +
    "levels×3.2+1.6м парапет) 2=угадано(дефолт 12м). " +
    "Просвет SRC_CLEARANCE растёт по мере падения уверенности.";
}

/**
 * Слепой дефолт 12 м заменяется медианой по ТИПУ здания из домов ТОГО ЖЕ города.
 *
 * Зачем. 12 метров — не «нет данных», а число, одинаковое для сарая и для жилой
 * башни. Замер 12.08.2026 по Астане: 22 дома с тегом `building=apartments`
 * летались как 12-метровые, при том что медиана таких домов в самом городе
 * 33.6 м, а 30 из 80 известных зданий этого типа выше 43 м — коридора, который
 * над слепым домом и строится (12 + 15 просвет + 16 страховки за `guessed`).
 * То есть у каждого третьего такого дома коридор прошёл бы ниже крыши.
 *
 * Почему это не «выдумать другое число». Медиана считается ТОЛЬКО по зданиям
 * того же типа в этом же городе, у которых высота известна, и только при трёх и
 * более свидетельствах. Город отвечает про себя сам; чужие нормативы и
 * справочники сюда не попадают.
 *
 * Что НЕ меняется: класс остаётся hs=2 (`guessed`) и получает те же 16 м
 * страховочного просвета. Медиана по типу — догадка получше, но догадка.
 *
 * Идёт ПОСЛЕ сверки с обмером (PLATEAU/NYC): там часть зданий переходит в hs=0,
 * и подставлять надо в окончательный набор угаданных, а не в промежуточный.
 */
const knownByType = new Map();
buildings.forEach((b, i) => {
  if (b.hs === 2) return;
  const t = buildingTypes[i] ?? "yes";
  if (!knownByType.has(t)) knownByType.set(t, []);
  knownByType.get(t).push(b.h);
});
/** Квантиль по возрастанию, линейная интерполяция между соседями. */
const quantile = (xs, p) => {
  const s = [...xs].sort((x, y) => x - y);
  const i = (s.length - 1) * p;
  const lo = Math.floor(i), hi = Math.ceil(i);
  return lo === hi ? s[lo] : s[lo] + (s[hi] - s[lo]) * (i - lo);
};
// `--no-type-median` оставляет слепой дефолт как был. Нужен не «на всякий
// случай»: без него нельзя отделить эффект этой подстановки от дрейфа самого
// OSM, а `--compare` показывает их одной цифрой «ячеек различается».
const noTypeMedian = process.argv.includes("--no-type-median");
let typedGuesses = 0, typedRaised = 0, typedLowered = 0, typedMaxDelta = 0;
for (let i = 0; !noTypeMedian && i < buildings.length; i++) {
  const b = buildings[i];
  if (b.hs !== 2) continue;
  const type = buildingTypes[i] ?? "yes";
  // `building=yes` — это «здание», и всё. Бакет нетипизированных домов ничего
  // не говорит о высоте: в Астане его медиана 11 м при 75-м процентиле 27 —
  // распределение смешанное, и подстановка сюда подняла бы 172 дома на пятнадцать
  // метров без основания. Предпосылка правила — «тип что-то сообщает»; здесь он
  // не сообщает ничего, значит остаётся слепой дефолт.
  if (UNINFORMATIVE_TYPES.has(type)) continue;
  const xs = knownByType.get(type);
  if (!xs || xs.length < TYPE_MEDIAN_MIN_SAMPLES) continue;
  // 75-й процентиль, а не медиана. Замер по Астане: при медиане (34 м у
  // `apartments`) ВЫШЕ получившегося коридора остаются 16 из 80 известных домов
  // этого типа — то есть половина исходной опасности сохраняется. При p75 (59 м)
  // не остаётся ни одного. Занижение здесь дороже завышения: завышение стоит
  // крюка, занижение — пролёта ниже крыши.
  //
  // И никогда НЕ опускаем ниже прежнего слепого дефолта: у угаданного здания
  // уменьшать запас не за что.
  const h = Math.max(DEFAULT_HEIGHT_M, Math.round(quantile(xs, TYPE_QUANTILE)));
  if (h === b.h) continue;
  if (h > b.h) typedRaised++; else typedLowered++;
  typedMaxDelta = Math.max(typedMaxDelta, Math.abs(h - b.h));
  b.h = h;
  typedGuesses++;
}
if (typedGuesses) {
  process.stderr.write(
    `  высота по 75-му процентилю своего типа: ${typedGuesses} зданий `
    + `(поднято ${typedRaised}, опущено ${typedLowered}, макс. сдвиг ${typedMaxDelta} м); `
    + `класс остался guessed\n`,
  );
  provenanceNote = provenanceNote.replace(
    "2=угадано(дефолт 12м)",
    `2=угадано(75-й процентиль высот этого же типа зданий в этом же городе, при ${TYPE_MEDIAN_MIN_SAMPLES}+ известных высотах и только для типов, которые о высоте что-то говорят; иначе дефолт ${DEFAULT_HEIGHT_M}м)`,
  );
}

const { heights, src } = rasterize(buildings, COLS, ROWS);

const measured = buildings.filter((b) => b.hs === 0).length;
const derived = buildings.filter((b) => b.hs === 1).length;
const guessed = buildings.filter((b) => b.hs === 2).length;
const total = buildings.length;
const round1 = (n) => Math.round(n * 10) / 10;

const committed = loadCommitted(city.committed);

if (compareOnly) {
  const cg = committed.grid;
  let cellsChanged = 0, blockedNow = 0, blockedBefore = 0;
  // Direction matters far more than the raw diff. A cell the twin calls EMPTY
  // that OSM now shows built on is an obstacle the router does not know about —
  // the twin would happily plan a corridor through it. The opposite direction
  // (twin blocked, OSM empty) only costs a detour.
  let unknownObstacle = 0, staleObstacle = 0, taller = 0;
  for (let i = 0; i < cg.heights.length; i++) {
    const now = heights[i] ?? 0, before = cg.heights[i];
    if (before > 0) blockedBefore++;
    if (now > 0) blockedNow++;
    if (now !== before) cellsChanged++;
    if (before === 0 && now > 0) unknownObstacle++;
    else if (before > 0 && now === 0) staleObstacle++;
    else if (now > before) taller++;
  }
  const pct = (n, d) => `${round1((100 * n) / Math.max(1, d))}%`;

  // A count produced by my own rasterizer proves little on its own. Name the
  // buildings standing on cells the twin calls empty, so a human can check the
  // finding against OSM instead of trusting it.
  // Where the unknown obstacles sit decides what this is. Clustered on the
  // border = an edge artefact of one of the two pipelines. Spread through the
  // interior = the committed twin is genuinely missing buildings. Sampling the
  // first N would have answered "row 0" purely because that is where scanning
  // starts, so spread the samples and count the split explicitly.
  const unknownIdx = [];
  for (let i = 0; i < cg.heights.length; i++) {
    if (cg.heights[i] === 0 && (heights[i] ?? 0) > 0) unknownIdx.push(i);
  }
  const isEdge = (i) => {
    const c = i % cg.cols, r = Math.floor(i / cg.cols);
    return c === 0 || r === 0 || c === cg.cols - 1 || r === cg.rows - 1;
  };
  const edgeCount = unknownIdx.filter(isEdge).length;
  // Which source the unknown obstacle comes from is the diagnosis: if most sit
  // on multipolygon relations, the pipeline that produced the committed twin
  // was querying ways only, and the gap is systematic rather than drift.
  const relCells = unknownIdx.filter((i) => {
    const c = i % cg.cols, r = Math.floor(i / cg.cols);
    const x = c * CELL + CELL / 2, y = r * CELL + CELL / 2;
    const b = buildings.findIndex((bd) => bd.h === heights[i] && inRing(bd.r, x, y));
    return b >= 0 && meta[b].id.startsWith("relation/");
  }).length;

  const outliers = heightOutliers(buildings);

  const samples = [];
  const step = Math.max(1, Math.floor(unknownIdx.length / 6));
  for (let k = 0; k < unknownIdx.length && samples.length < 6; k += step) {
    const i = unknownIdx[k];
    const c = i % cg.cols, r = Math.floor(i / cg.cols);
    const x = c * CELL + CELL / 2, y = r * CELL + CELL / 2;
    const b = buildings.findIndex((bd) => bd.h === heights[i] && inRing(bd.r, x, y));
    if (b >= 0) samples.push(`    cell ${c},${r} h=${heights[i]}m  ${meta[b].id}${meta[b].name ? ` — ${meta[b].name}` : ""}`);
  }
  process.stderr.write(
    `\n── ${cityId}: OSM today vs committed twin (${committed.dataQuality.source}) ──\n` +
    `grid                ${COLS}×${ROWS} vs ${cg.cols}×${cg.rows}${COLS === cg.cols && ROWS === cg.rows ? "  ✓ same" : "  ✗ DIFFERENT"}\n` +
    `buildings           ${total} vs ${committed.buildings.length}\n` +
    `measured heights    ${measured} (${pct(measured, total)}) vs ${committed.dataQuality.measured} (${committed.dataQuality.measuredPct}%)\n` +
    `real (meas+derived) ${pct(measured + derived, total)} vs ${committed.dataQuality.realPct}%\n` +
    `blocked cells       ${blockedNow} vs ${blockedBefore}\n` +
    `cells differing     ${cellsChanged} of ${cg.heights.length} (${pct(cellsChanged, cg.heights.length)})\n` +
    `\n  ⚠ twin EMPTY, OSM built   ${unknownObstacle}  ← obstacles the router cannot see\n` +
    `      on the grid border     ${edgeCount} (${pct(edgeCount, unknownObstacle)}) — the rest are interior, so not an edge artefact\n` +
    `      from multipolygons     ${relCells} (${pct(relCells, unknownObstacle)}) — building relations, i.e. large complexes\n` +
    `    twin built, OSM empty    ${staleObstacle}  (costs a detour, not a collision)\n` +
    `    both built, OSM taller   ${taller}\n` +
    (samples.length ? `\n  buildings on cells the twin calls empty (verifiable in OSM):\n${samples.join("\n")}\n` : "") +
    (outliers.length
      ? `\n  ⚠ heights towering over the rest of the city — check the tag, not the sky:\n` +
        outliers.slice(0, 5).map((o) =>
          `    ${o.h} m = ${o.times}x the 99th percentile` +
          `${o.hs === 0 ? " and TRUSTED as measured, so flown with zero safety clearance" : ""}\n`).join("") +
        `    A real skyline tapers, a wrong tag does not. Astana 2026-07-27: height=382 on a 75-storey tower.\n`
      : "") +
    `\n` +
    `Drift is expected — OSM is live. Judge by whether provenance IMPROVED\n` +
    `(more measured heights) before overwriting a committed twin, and treat a\n` +
    `large "twin EMPTY, OSM built" count as a safety finding, not a diff.\n`,
  );
  process.exit(0);
}

const suspect = [
  ...heightOutliers(buildings).map((o) => ({ i: o.index, h: o.h, times: o.times, why: "towers over the city" })),
  ...contradicted.map((c) => ({ i: c.i, h: c.h, was: c.was, levels: c.levels, why: "height tag contradicted its own floor count" })),
];
if (suspect.length) {
  process.stderr.write(
    `  ⚠ ${suspect.length} height(s) the source could not vouch for: ` +
    `${suspect.map((o) => (o.times ? `${o.h} m (${o.times}x p99)` : `${o.was} m over ${o.levels} floors → ${o.h} m`)).join(", ")}
`,
  );
}

const data = {
  city: city.name,
  bbox: city.bbox,
  meters: { w: W, h: H },
  grid: { cols: COLS, rows: ROWS, cell: CELL, heights, src },
  // `stated` — служебный признак этапа сверки, а не часть твина: в объявленном
  // CityData его нет, и в отгружаемом файле ему делать нечего.
  buildings: buildings.map(({ h, hs, r }) => ({ h, hs, r })),
  vertiports: city.vertiports ?? committed.vertiports,
  dataQuality: {
    total, measured, derived, guessed,
    measuredPct: round1((100 * measured) / total),
    realPct: round1((100 * (measured + derived)) / total),
    source: sourceLabel,
    note: provenanceNote,
    // Published rather than merely printed: the twin trusts a height tag
    // absolutely (hs=0 gets zero safety clearance), so a tag that cannot be
    // right has to reach whoever is looking at the city, not just whoever
    // regenerates it. Omitted entirely when clean, so a quiet city stays quiet.
    ...(suspect.length ? { suspect } : {}),
  },
};

const out = `${city.header}\nexport const ${city.exportName}: CityData = ${JSON.stringify(data)};\n`;
if (process.argv.includes("--write")) {
  fs.writeFileSync(new URL(`../src/routes/${city.committed}`, import.meta.url), out);
  process.stderr.write(`wrote src/routes/${city.committed}\n`);
} else {
  process.stdout.write(out);
}
process.stderr.write(
  `done: ${total} buildings, ${measured} measured (${data.dataQuality.measuredPct}%), grid ${COLS}×${ROWS}\n`,
);
